import type { gsap } from 'gsap';
import { regularTiling, type Vec2 } from 'poincare-ball';
import { Camera } from '../lib/camera';
import { C, ball, pathGeodesic, depthRamp, rgba, type Viewport } from '../lib/draw';
import type { Scene, World } from './manager';

/** Tiles whose Euclidean size on screen is below this (CSS px) are not drawn; they are sub-pixel texture at the rim. */
const MIN_TILE_PX = 1.6;

/**
 * Chapter 0: the {7,3} tiling of the hyperbolic plane, generated by reflection in the
 * TypeScript package, breathing slowly under the title. Scroll adds a hyperbolic
 * parallax (the camera focus moves along a geodesic), and the hand-off to chapter 01
 * dissolves it into the flat tree.
 *
 * Cost per frame matters here because this scene runs at page load, on the main thread, in
 * software when there is no GPU: the tiles are drawn without a clip (one fill and one stroke
 * each, no mask), the two full-screen gradients (the lens halo under the tiling and the
 * vignette over it) are DOM layers composited off the main thread rather than canvas fills,
 * and the ambient loop runs at 30 frames per second (the breathing has a period of about 27 s).
 * Measured in headless Chrome without a GPU: about 6 ms a frame at 1350×940, 7 ms at 412×823@1.75.
 */
export class HeroScene implements Scene {
  readonly id = 'hero';
  readonly layout = 'hero';
  readonly loop = true;
  readonly loopFps = 30;
  readonly diskAlpha = 0;
  presence = 1;
  /** Scroll parallax, 0 at the top of the page, 1 when chapter 01 arrives. */
  readonly par = { t: 0 };

  private tiles = regularTiling(7, 3, 6, { maxNorm: 0.985, angle: Math.PI / 14 });
  private maxDepth = Math.max(...this.tiles.map((t) => t.depth));
  private halo = document.querySelector<HTMLElement>('.hero-halo');
  private vignette = document.querySelector<HTMLElement>('.hero-vignette');
  private haloKey = '';
  private layerAlpha = -1;

  build(_tl: gsap.core.Timeline): void {}

  /** Geometry and opacity of the two gradient layers, written only when they change. */
  private syncLayers(vp: Viewport, a: number): void {
    const key = `${vp.cx},${vp.cy},${vp.R}`;
    if (this.halo && key !== this.haloKey) {
      this.haloKey = key;
      const r = vp.R * 1.6;
      this.halo.style.width = `${2 * r}px`;
      this.halo.style.height = `${2 * r}px`;
      this.halo.style.transform = `translate(${vp.cx - r}px, ${vp.cy - r}px)`;
    }
    const alpha = a <= 0.004 ? 0 : Math.min(1, a);
    if (alpha !== this.layerAlpha) {
      this.layerAlpha = alpha;
      const o = alpha.toFixed(3);
      if (this.halo) this.halo.style.opacity = o;
      if (this.vignette) this.vignette.style.opacity = o;
    }
  }

  draw(ctx: CanvasRenderingContext2D, vp: Viewport, world: World): void {
    const a = this.presence;
    this.syncLayers(vp, a);
    if (a <= 0.004) return;
    const t = world.time;
    const breathe = 0.08 + 0.035 * Math.sin(t * 0.23);
    const ambient: Vec2 = [breathe * Math.cos(t * 0.11), breathe * Math.sin(t * 0.17)];
    const slide = ball.pointAt([0.25, -1], 0.05 + 0.9 * this.par.t);
    const focus = ball.mobiusAdd(slide as number[], ambient) as Vec2;
    const cam = Camera.fromFocusTheta([focus[0], focus[1]], 0.04 * Math.sin(t * 0.07) + 0.28 * this.par.t);

    ctx.save();
    ctx.globalAlpha = a;
    ctx.lineWidth = 1;
    // No clip: every tile lies inside the unit disk by construction (and the camera keeps it there), and a
    // soft circular clip would route every fill and stroke through a mask, tripling the frame cost.
    const minSize = MIN_TILE_PX / vp.R;
    const md = Math.max(1, this.maxDepth);
    for (const tile of this.tiles) {
      const c = cam.apply(tile.center);
      const n2 = c[0] * c[0] + c[1] * c[1];
      // Euclidean size of the tile shrinks like (1 − |c|²); skip sub-pixel tiles.
      if ((1 - n2) * 0.3 < minSize) continue;
      const vs = tile.vertices.map((v) => cam.apply(v));
      const fade = Math.max(0.15, 1 - Math.pow(n2, 2.5));
      ctx.beginPath();
      for (let i = 0; i < vs.length; i++) pathGeodesic(ctx, vp, vs[i], vs[(i + 1) % vs.length]);
      ctx.fillStyle = depthRamp(1 - tile.depth / md, 0.075 * fade);
      ctx.fill();
      ctx.strokeStyle = rgba(C.fog, 0.24 * fade);
      ctx.stroke();
    }
    ctx.restore();

    ctx.save();
    ctx.globalAlpha = a;
    ctx.lineWidth = 1.25;
    ctx.strokeStyle = rgba(C.fog, 0.35);
    ctx.beginPath();
    ctx.arc(vp.cx, vp.cy, vp.R, 0, Math.PI * 2);
    ctx.stroke();
    ctx.restore();
  }
}
